module Alu(
  input  [4:0]  op,
  input  [31:0] decoded_pc,
                decoded_imm,
  input  [2:0]  decoded_branchOp,
  input         decoded_isJal,
                decoded_isJalr,
  input  [31:0] a,
                b,
  output [31:0] result,
                link,
  output        branchTaken,
  output [31:0] target
);

  wire [63:0] _GEN = {32'h0, b};
  wire [63:0] unsignedProduct = {32'h0, a} * _GEN;
  wire [63:0] _GEN_0 = {{32{a[31]}}, a};
  wire [63:0] signedProduct = _GEN_0 * {{32{b[31]}}, b};
  wire [63:0] _signedUnsignedProduct_T_4 = _GEN_0 * _GEN;
  wire        divByZero = b == 32'h0;
  wire        signedOverflow = a == 32'h80000000 & (&b);
  wire [32:0] signedQuotient =
    $unsigned($signed($signed({a[31], a}) / $signed({b[31], b})));
  wire [62:0] _result_T_4 = {31'h0, a} << b[4:0];
  wire        lessU = a < b;
  wire [31:0] _GEN_1 = {27'h0, b[4:0]};
  reg         casez_tmp;
  wire        _branchTaken_T_4 = decoded_branchOp == 3'h0 & a == b;
  always_comb begin
    casez (decoded_branchOp)
      3'b000:
        casez_tmp = _branchTaken_T_4;
      3'b001:
        casez_tmp = a != b;
      3'b010:
        casez_tmp = $signed(a) < $signed(b);
      3'b011:
        casez_tmp = $signed(a) >= $signed(b);
      3'b100:
        casez_tmp = lessU;
      3'b101:
        casez_tmp = a >= b;
      3'b110:
        casez_tmp = _branchTaken_T_4;
      default:
        casez_tmp = _branchTaken_T_4;
    endcase
  end // always_comb
  wire [31:0] _registerTarget_T = a + decoded_imm;
  assign result =
    op == 5'h11
      ? (divByZero ? a : a % b)
      : op == 5'h10
          ? (divByZero ? a : signedOverflow ? 32'h0 : $signed($signed(a) % $signed(b)))
          : op == 5'hF
              ? (divByZero ? 32'hFFFFFFFF : a / b)
              : op == 5'hE
                  ? (divByZero ? 32'hFFFFFFFF : signedOverflow ? a : signedQuotient[31:0])
                  : op == 5'hD
                      ? unsignedProduct[63:32]
                      : op == 5'hC
                          ? _signedUnsignedProduct_T_4[63:32]
                          : op == 5'hB
                              ? signedProduct[63:32]
                              : op == 5'hA
                                  ? unsignedProduct[31:0]
                                  : op == 5'h9
                                      ? a & b
                                      : op == 5'h8
                                          ? a | b
                                          : op == 5'h7
                                              ? $signed($signed(a) >>> _GEN_1)
                                              : op == 5'h6
                                                  ? a >> _GEN_1
                                                  : op == 5'h5
                                                      ? a ^ b
                                                      : op == 5'h4
                                                          ? {31'h0, lessU}
                                                          : op == 5'h3
                                                              ? {31'h0,
                                                                 $signed(a) < $signed(b)}
                                                              : op == 5'h2
                                                                  ? _result_T_4[31:0]
                                                                  : op == 5'h1
                                                                      ? a - b
                                                                      : op == 5'h0
                                                                          ? a + b
                                                                          : 32'h0;
  assign link = decoded_pc + 32'h4;
  assign branchTaken = casez_tmp | decoded_isJal | decoded_isJalr;
  assign target =
    decoded_isJalr ? {_registerTarget_T[31:1], 1'h0} : decoded_pc + decoded_imm;
endmodule

