// VCS coverage exclude_file
module ram_8x69(
  input  [2:0]  R0_addr,
  input         R0_en,
                R0_clk,
  output [68:0] R0_data,
  input  [2:0]  W0_addr,
  input         W0_en,
                W0_clk,
  input  [68:0] W0_data
);

  reg [68:0] Memory[0:7];
  always @(posedge W0_clk) begin
    if (W0_en)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 69'bx;
endmodule

module Queue8_StoreRequest(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [31:0] io_enq_bits_addr,
                io_enq_bits_data,
  input  [3:0]  io_enq_bits_strobe,
  input         io_enq_bits_isExit,
                io_deq_ready,
  output        io_deq_valid,
  output [31:0] io_deq_bits_addr,
                io_deq_bits_data,
  output [3:0]  io_deq_bits_strobe,
  output        io_deq_bits_isExit,
  output [3:0]  io_count
);

  wire [68:0] _ram_ext_R0_data;
  reg  [2:0]  enq_ptr_value;
  reg  [2:0]  deq_ptr_value;
  reg         maybe_full;
  wire        ptr_match = enq_ptr_value == deq_ptr_value;
  wire        empty = ptr_match & ~maybe_full;
  wire        full = ptr_match & maybe_full;
  wire        do_enq = ~full & io_enq_valid;
  wire        do_deq = io_deq_ready & ~empty;
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 3'h0;
      deq_ptr_value <= 3'h0;
      maybe_full <= 1'h0;
    end
    else begin
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 3'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 3'h1;
      if (do_enq != do_deq)
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_8x69 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data
      ({io_enq_bits_addr, io_enq_bits_data, io_enq_bits_strobe, io_enq_bits_isExit})
  );
  assign io_enq_ready = ~full;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_addr = _ram_ext_R0_data[68:37];
  assign io_deq_bits_data = _ram_ext_R0_data[36:5];
  assign io_deq_bits_strobe = _ram_ext_R0_data[4:1];
  assign io_deq_bits_isExit = _ram_ext_R0_data[0];
  assign io_count = {full, enq_ptr_value - deq_ptr_value};
endmodule

